# frozen_string_literal: true

RSpec.describe RuboCop::TodoPruner do
  subject(:pruner) { described_class.new(source) }

  let(:source) { <<~YAML }
    # This configuration was generated by
    # `rubocop --auto-gen-config`
    # using RuboCop version 1.88.2.
    # The point is for the user to remove these configuration records
    # one by one as the offenses are removed from the code base.

    # Offense count: 3
    # This cop supports safe autocorrection (--autocorrect).
    Lint/UselessAssignment:
      Exclude:
        - 'lib/a.rb'
        - 'lib/b.rb'

    # Offense count: 2
    Metrics/MethodLength:
      Max: 42

    # Offense count: 4
    Security/Eval:
      Exclude:
        - 'lib/a.rb'
        - 'lib/c.rb'

    Style/FrozenStringLiteralComment:
      Exclude:
        - '**/*.arb'
        - 'lib/d.rb'
        - !ruby/regexp /generated/

    # Offense count: 100
    Style/Documentation:
      Enabled: false
  YAML

  describe '#matrix' do
    it 'maps each cop to the verifiable files of its Exclude list' do
      expect(pruner.matrix).to eq(
        'Lint/UselessAssignment' => ['lib/a.rb', 'lib/b.rb'],
        'Security/Eval' => ['lib/a.rb', 'lib/c.rb'],
        'Style/FrozenStringLiteralComment' => ['lib/d.rb']
      )
    end

    it 'does not include entries without an Exclude list' do
      expect(pruner.matrix.keys).not_to include('Metrics/MethodLength', 'Style/Documentation')
    end
  end

  describe '#prune' do
    def prune(checked_cops:, offenses:)
      pruner.prune(
        checked_cops: checked_cops,
        keep: ->(cop, path) { offenses.fetch(cop, {}).key?(path) },
        count: ->(cop, path) { offenses.fetch(cop, {})[path] }
      )
    end

    context 'when nothing was fixed' do
      it 'returns the source unchanged, byte for byte' do
        result = prune(
          checked_cops: Set['Lint/UselessAssignment', 'Security/Eval',
                            'Style/FrozenStringLiteralComment'],
          offenses: {
            'Lint/UselessAssignment' => { 'lib/a.rb' => 1, 'lib/b.rb' => 2 },
            'Security/Eval' => { 'lib/a.rb' => 2, 'lib/c.rb' => 2 },
            'Style/FrozenStringLiteralComment' => { 'lib/d.rb' => 1 }
          }
        )
        expect(result.output).to eq(source)
        expect(result.removed_items).to eq(0)
        expect(result.removed_entries).to eq(0)
      end
    end

    context 'when one file of an entry was fixed' do
      it 'removes the file and updates the offense count' do
        result = prune(
          checked_cops: Set['Lint/UselessAssignment'],
          offenses: { 'Lint/UselessAssignment' => { 'lib/b.rb' => 2 } }
        )
        expect(result.removed_items).to eq(1)
        expect(result.removed_entries).to eq(0)
        expect(result.output).to include(<<~YAML)
          # Offense count: 2
          # This cop supports safe autocorrection (--autocorrect).
          Lint/UselessAssignment:
            Exclude:
              - 'lib/b.rb'
        YAML
        expect(result.output)
          .not_to include("Lint/UselessAssignment:\n  Exclude:\n    - 'lib/a.rb'")
      end
    end

    context 'when all files of an entry were fixed' do
      it 'removes the whole entry including its comments and separator' do
        result = prune(checked_cops: Set['Lint/UselessAssignment'], offenses: {})
        expect(result.removed_items).to eq(2)
        expect(result.removed_entries).to eq(1)
        expect(result.output).not_to include('Lint/UselessAssignment', '# Offense count: 3')
        # The neighboring entries stay separated by exactly one blank line.
        expect(result.output).to include(<<~YAML)
          # one by one as the offenses are removed from the code base.

          # Offense count: 2
          Metrics/MethodLength:
        YAML
      end
    end

    context 'when the count of unknown-count files is nil' do
      it 'keeps the offense count comment unchanged' do
        result = pruner.prune(
          checked_cops: Set['Security/Eval'],
          keep: ->(_cop, path) { path != 'lib/c.rb' },
          count: ->(_cop, _path) {}
        )
        expect(result.output).to include("# Offense count: 4\nSecurity/Eval:")
        expect(result.output).not_to include("- 'lib/c.rb'")
      end
    end

    context 'with unverifiable Exclude items' do
      it 'keeps globs and regexps and never removes the entry' do
        result = prune(checked_cops: Set['Style/FrozenStringLiteralComment'], offenses: {})
        expect(result.output).to include("- '**/*.arb'", '- !ruby/regexp /generated/')
        expect(result.output).to include('Style/FrozenStringLiteralComment:')
        expect(result.output).not_to include("- 'lib/d.rb'")
        expect(result.removed_entries).to eq(0)
      end
    end

    context 'when a cop was not checked' do
      it 'leaves its entry untouched' do
        result = prune(checked_cops: Set['Security/Eval'],
                       offenses: { 'Security/Eval' => { 'lib/a.rb' => 2, 'lib/c.rb' => 2 } })
        expect(result.output)
          .to include("Lint/UselessAssignment:\n  Exclude:\n    - 'lib/a.rb'\n    - 'lib/b.rb'")
      end
    end

    it 'never touches entries without an Exclude list' do
      result = prune(checked_cops: Set['Metrics/MethodLength', 'Style/Documentation'], offenses: {})
      expect(result.output).to include("Metrics/MethodLength:\n  Max: 42")
      expect(result.output).to include("Style/Documentation:\n  Enabled: false")
    end
  end
end
